referenceSolutions.javascript:
export function solve(commands) {
  let x = 0,
    y = 0,
    d = 0;
  const vectors = [
    [1, 0],
    [0, 1],
    [-1, 0],
    [0, -1],
  ];
  for (const [op, n] of commands) {
    if (op === "forward") {
      x += vectors[d][0] * n;
      y += vectors[d][1] * n;
    } else d = (d + (op === "left" ? n : -n) + 4) % 4;
  }
  return { position: [x, y], direction: ["east", "north", "west", "south"][d] };
}

